/* BCM1280/BCM1480 Interrupt Mapper definitions. */
/* Dependency: <asm/sibyte/sb1250_defs.h> supplies the _SB_* bit helpers. */

pub const K_BCM1480_INT_SOURCES: u64 = 128;

pub const fn _BCM1480_INT_HIGH(k: u64) -> u64 { k }
pub const fn _BCM1480_INT_LOW(k: u64) -> u64 { k + 64 }
pub const fn _BCM1480_INT_MASK(w: u64, n: u64) -> u64 { ((1u64 << w) - 1) << (n & 0x3f) }
pub const fn _BCM1480_INT_MASK1(n: u64) -> u64 { 1u64 << (n & 0x3f) }
pub const fn _BCM1480_INT_OFFSET(n: u64) -> u64 { (n & 0x40) << 6 }

